android.extraProguardRules:
# ── React Native: the two rules that matter most ─────────────────────
# JNI entry points are called from C++ by name. R8 cannot see those calls,
# so without this it strips or renames them and the failure is a runtime
# UnsatisfiedLinkError — or worse, a module that silently does nothing.
-keepclasseswithmembernames,includedescriptorclasses class * { native <methods>; }

# @DoNotStrip is how RN and its module ecosystem mark reflection/JNI targets.
-keep,allowobfuscation @interface com.facebook.proguard.annotations.DoNotStrip
-keep @com.facebook.proguard.annotations.DoNotStrip class * { *; }
-keepclassmembers class * { @com.facebook.proguard.annotations.DoNotStrip *; }
-keepclassmembers class * { @com.facebook.react.uimanager.annotations.ReactProp <methods>; }
-keepclassmembers class * { @com.facebook.react.bridge.ReactMethod <methods>; }

# ── Bridge / JSI surfaces ────────────────────────────────────────────
-keep class com.facebook.react.bridge.** { *; }
-keep class com.facebook.react.turbomodule.** { *; }
-keep class com.facebook.jni.** { *; }
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.soloader.** { *; }

# ── Nitro modules ────────────────────────────────────────────────────
# Was com.margelo.quickcrypto.** — WRONG package, so quick-crypto and the
# whole Nitro HybridObject registry went unprotected. Real package tree is
# com.margelo.nitro.* (core + quickcrypto + the Rust CryptoCore binding).
-keep class com.margelo.nitro.** { *; }

# ── Native modules reached by reflection / JNI ───────────────────────
-keep class com.op.sqlite.** { *; }
-keep class expo.modules.** { *; }
-keep class com.swmansion.** { *; }
-keep class com.th3rdwave.safeareacontext.** { *; }
-keep class org.webrtc.** { *; }
-keep class com.oney.WebRTCModule.** { *; }
-keep class io.livekit.** { *; }
-keep class com.mrousavy.** { *; }
-keep class io.invertase.** { *; }
-keep class app.notifee.** { *; }

# ── Crash reports stay readable ──────────────────────────────────────
-keepattributes SourceFile,LineNumberTable,*Annotation*,Signature,InnerClasses,EnclosingMethod
-keep class io.sentry.** { *; }
